package com.enterprise.graphql;

import org.springframework.graphql.data.method.annotation.Argument;
import org.springframework.graphql.data.method.annotation.MutationMapping;
import org.springframework.graphql.data.method.annotation.QueryMapping;
import org.springframework.graphql.data.method.annotation.SubscriptionMapping;
import org.springframework.stereotype.Controller;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Sinks;

@Controller
public class OrderGraphController {

    private final Sinks.Many<Order> orderSink = Sinks.many().multicast().onBackpressureBuffer();

    @QueryMapping
    public Order getOrderById(@Argument Long id) {
        return OrderRepository.findById(id);
    }

    @MutationMapping
    public Order createOrder(@Argument OrderInput input) {
        Order savedOrder = OrderRepository.save(new Order(input.item(), input.quantity()));
        orderSink.tryEmitNext(savedOrder);
        return savedOrder;
    }

    @SubscriptionMapping
    public Flux<Order> orderCreated() {
        return orderSink.asFlux();
    }
}
